class Solution{
    int res = 0;
    int K = 0;
    public int kthSmallest(TreeNode root,int k){
        this.K = k;
        dfs(root);
        return res;
    }
    public void dfs(TreeNode root){
        if(root==null)
            return;
        dfs(root.left);
        K--;
        if(K==0){
            res = root.val;
            return;
        }
        dfs(root.right);
    }
}
